svg.script:
{
  "metadata": {"title": "Network Architecture", "projectName": "Food Delivery System", "description": "Network topology and connectivity design", "version": "1.0", "mode": "light"},
  "config": {"layout": {"canvasWidth": 1920, "canvasHeight": 1080}, "styling": {"mode": "light", "canvasColor": "#FFFFFF", "fillColor": "#E5E5E5", "strokeColor": "#1A1A1A"}},
  "data": {
    "zones": [
      {"id": "internet", "name": "Internet Zone", "x": 100, "y": 200, "width": 450, "height": 250},
      {"id": "dmz", "name": "DMZ", "x": 650, "y": 200, "width": 450, "height": 250},
      {"id": "internal", "name": "Internal Network", "x": 1200, "y": 200, "width": 450, "height": 250}
    ]
  }
}

(function() {
  const dataElement = document.currentScript.closest('svg').querySelector('#network-architecture-data');
  if (!dataElement) return;
  try {
    const data = JSON.parse(dataElement.textContent);
    console.log('[Network Architecture Data] Loaded:', data.metadata.title);
  } catch (e) {
    console.error('[Network Architecture] Invalid JSON:', e.message);
  }
})();
